14	// This file guards long physical records for the legacy single-watermark
15	// fixed-window entry point RunAggregate. The line collector starts with a
16	// 64 KiB buffer and grows it, so a single valid record longer than 64 KiB or
17	// 128 KiB -- long because its event key is long, with multibyte (Chinese)
18	// characters -- must aggregate exactly like short records: same-key events
19	// merge with the right count and sum and the whole key is preserved, two keys
20	// differing only at the tail stay two windows, windows close only when the
21	// watermark reaches their end (never early or twice just because a line was
22	// long), and the byte-identical stream must give byte-identical windows, late
23	// notices and success/failure no matter how it is split across reads,
24	// including cuts inside a multibyte character or on the line delimiter.
25	//
26	// Read-failure semantics with a long line in flight get their own checks: the
27	// unterminated tail of a long record is never an event (no count, no late
28	// notice), previously emitted windows stay, and the reader's own error
29	// surfaces; complete records whose newline already arrived -- even in the
30	// same Read that carried the error -- are processed in order first.
31	
32	const (
33		longKeyPrefix  = "长传感器记录-"
34		longKeyBlock   = "温湿度读数" // 6 runes, 18 UTF-8 bytes per repetition
35		longKeySuffixA = "-甲"    // key A ending
36		longKeySuffixB = "-乙"    // key B: identical length and prefix, differs only at the tail
37	)
38	
39	// longKey builds a key whose repeated multibyte middle makes records using it
40	// longer than thresholdBytes. Suffix A and B keys have equal length and share
41	// every byte except the final rune, so a collector that truncated by length
42	// would wrongly merge the two.
43	func longKey(suffix string, thresholdBytes int) string {
44		repeat := thresholdBytes/len(longKeyBlock) + 40
45		return longKeyPrefix + strings.Repeat(longKeyBlock, repeat) + suffix
46	}
47	
48	// longRecordScenario holds the reference fixed-window stream and its expected
49	// results. Window length is 1000ms; physical layout is:
50	//
51	//	line  1: blank
52	//	line  2: event key 短 time=100 value=2
53	//	line  3: watermark 1000                      -> closes [0,1000)
54	//	line  4: blank
55	//	line  5: LONG event keyA time=1100 value=10
56	//	line  6: short event key 短 time=1150 value=4
57	//	line  7: LONG event keyA time=1200 value=5
58	//	line  8: blank
59	//	line  9: LONG event keyB time=1150 value=7
60	//	line 10: short event key 短 time=100 value=8  -> late vs watermark 1000, skipped
61	//	line 11: watermark 2000                      -> closes [1000,2000)
62	//	line 12: blank
63	//	line 13: late event time=1500                -> late vs watermark 2000, skipped
64	//	line 14: event time=2500 value=99            -> open window, must never be emitted
65	//
66	// Long and short records alternate around the two 64 KiB+ lines keyA lines,
67	// blanks flank them, one read can carry the end of a short record together
68	// with the start of a long one, and both late notices sit after long records
69	// so their physical line numbers must survive buffer growth.
70	type longRecordScenario struct {
71		input     string
72		keyA      string
73		keyB      string
74		longLines []int // physical line numbers that carry the long records
75		wantOut   string
76		wantLate  string
77	}
78	
79	func buildLongRecordScenario(t *testing.T, thresholdBytes int) longRecordScenario {
80		t.Helper()
81		keyA := longKey(longKeySuffixA, thresholdBytes)
82		keyB := longKey(longKeySuffixB, thresholdBytes)
83		ev := func(key string, time, value int) string {
84			return fmt.Sprintf(`{"type":"event","key":%q,"time":%d,"value":%d}`, key, time, value)
85		}
86		lines := []string{
87			``, // 1 blank
88			ev("短", 100, 2),
89			`{"type":"watermark","time":1000}`,
90			``, // 4 blank
91			ev(keyA, 1100, 10),
92			ev("短", 1150, 4),
93			ev(keyA, 1200, 5),
94			``, // 8 blank
95			ev(keyB, 1150, 7),
96			ev("短", 100, 8), // 10 late below watermark 1000
97			`{"type":"watermark","time":2000}`,
98			``,                  // 12 blank
99			ev("迟到事件", 1500, 3), // 13 late below watermark 2000
100			ev("不输出窗口", 2500, 99),
101		}
102		input := strings.Join(lines, "\n") + "\n"
103	
104		// The long lines must actually cross the threshold; pin that rather than
105		// trusting the repeat arithmetic silently.
106		lineAt := func(n int) string {
107			start, end := physicalLineRange(input, n)
108			return input[start:end]
109		}
110		for _, n := range []int{5, 7, 9} {
111			if len(lineAt(n)) <= thresholdBytes {
112				t.Fatalf("line %d is %d bytes, want a record longer than %d", n, len(lineAt(n)), thresholdBytes)
113			}
114		}
115		if len(keyA) != len(keyB) {
116			t.Fatalf("test keys must be equal length: %d vs %d", len(keyA), len(keyB))
117		}
118		if !strings.HasPrefix(keyB, keyA[:len(keyA)-len(longKeySuffixA)]) {
119			t.Fatalf("key B must share key A's full prefix and differ only at the tail")
120		}
121	
122		// Expected windows, ordered by end then key in UTF-8 byte order. Derive the
123		// [1000,2000) key order from the keys themselves instead of hardcoding it:
124		// 短 sorts before the 长-prefixed long keys, and suffix 乙 (E4 B9 99) sorts
125		// before suffix 甲 (E7 94 B2).
126		first := AggregateResult{Key: "短", Start: 0, End: 1000, Count: 1, Sum: 2}
127		secondGroup := []AggregateResult{
128			{Key: keyA, Start: 1000, End: 2000, Count: 2, Sum: 15},
129			{Key: keyB, Start: 1000, End: 2000, Count: 1, Sum: 7},
130			{Key: "短", Start: 1000, End: 2000, Count: 1, Sum: 4},
131		}
132		sort.Slice(secondGroup, func(i, j int) bool { return secondGroup[i].Key < secondGroup[j].Key })
133		var b strings.Builder
134		for _, r := range append([]AggregateResult{first}, secondGroup...) {
135			encoded, err := json.Marshal(r)
136			if err != nil {
137				t.Fatalf("marshal expected result: %v", err)
138			}
139			b.Write(encoded)
140			b.WriteByte('\n')
141		}
142		return longRecordScenario{
143			input:     input,
144			keyA:      keyA,
145			keyB:      keyB,
146			longLines: []int{5, 7, 9},
147			wantOut:   b.String(),
148			wantLate: "line 10: late event time=100 below current watermark 1000, skipped\n" +
149				"line 13: late event time=1500 below current watermark 2000, skipped\n",
150		}
151	}
152	
153	// physicalLineRange returns the byte offsets [start,end) of physical line n
154	// (1-based), excluding its trailing '\n'. Blank lines yield start == end.
155	func physicalLineRange(input string, n int) (start, end int) {
156		line := 1
157		start = 0
158		for i := 0; i < len(input); i++ {
159			if input[i] == '\n' {
160				if line == n {
161					return start, i
162				}
163				line++
164				start = i + 1
165			}
166		}
167		if line == n {
168			return start, len(input)
169		}
170		return 0, 0
171	}
172	
173	// runFixedOnce runs RunAggregate over the given delivery of the stream.
174	func runFixedOnce(t *testing.T, r io.Reader) (string, string, error) {
175		t.Helper()
176		var out, late bytes.Buffer
177		err := RunAggregate(r, 1000, &out, &late)
178		return out.String(), late.String(), err
179	}
180	
181	// assertReferenceResult checks the full invariant: windows, late notices,
182	// success, no early/duplicate window rows and no flush of the still-open
183	// window, plus full key fidelity for the long keys.
184	func assertReferenceResult(t *testing.T, sc longRecordScenario, out, late string, err error) {
185		t.Helper()
186		if err != nil {
187			t.Fatalf("unexpected error: %v", err)
188		}
189		if out != sc.wantOut {
190			t.Fatalf("window output mismatch:\n got: %q\nwant: %q", out, sc.wantOut)
191		}
192		if late != sc.wantLate {
193			t.Fatalf("late notice mismatch:\n got: %q\nwant: %q", late, sc.wantLate)
194		}
195		if strings.Contains(out, `"end":3000`) {
196			t.Fatalf("the still-open window of the time=2500 event must not flush at end of input: %q", out)
197		}
198	
199		// Every output object must parse; the long keys must come through whole
200		// (not truncated, not mojibake) and the tail-differing keys must be
201		// separate rows.
202		byKey := map[string][]AggregateResult{}
203		var ends []int64
204		for i, line := range strings.Split(strings.TrimSuffix(out, "\n"), "\n") {
205			var r AggregateResult
206			if jerr := json.Unmarshal([]byte(line), &r); jerr != nil {
207				t.Fatalf("output line %d is not valid JSON: %v\nline: %.80q...", i+1, jerr, line)
208			}
209			byKey[r.Key] = append(byKey[r.Key], r)
210			ends = append(ends, r.End)
211		}
212		gotA, okA := byKey[sc.keyA]
213		gotB, okB := byKey[sc.keyB]
214		if !okA || !okB {
215			t.Fatalf("long keys must be preserved in full as separate rows; got key A present=%v, key B present=%v", okA, okB)
216		}
217		if len(gotA) != 1 || gotA[0].Count != 2 || gotA[0].Sum != 15 {
218			t.Fatalf("key A window = %+v, want one [1000,2000) row count=2 sum=15", gotA)
219		}
220		if len(gotB) != 1 || gotB[0].Count != 1 || gotB[0].Sum != 7 {
221			t.Fatalf("key B window = %+v, want one [1000,2000) row count=1 sum=7", gotB)
222		}
223		if !sort.SliceIsSorted(ends, func(i, j int) bool { return ends[i] < ends[j] }) {
224			t.Fatalf("window ends must be emitted ascending: %v", ends)
225		}
226	}
227	
228	// longRecordDeliverySchedules builds read schedules that stress the buffer's
229	// growth path, multibyte boundaries and line delimiters for this input:
230	// one-shot, tiny uniform reads, reads aligned (and off by one/two) with the
231	// 64 KiB and 128 KiB growth boundaries, and targeted two-read cuts on the
232	// newline before/after each long line.
233	func longRecordDeliverySchedules(t *testing.T, sc longRecordScenario, tinySizes []int) map[string][]int {
234		t.Helper()
235		schedules := map[string][]int{
236			"one-shot": nil,
237		}
238		for _, size := range tinySizes {
239			schedules[fmt.Sprintf("uniform-%d", size)] = uniformCuts(len(sc.input), size)
240		}
241		// Cuts around the 128 KiB boundary only matter (and are cheap enough) for
242		// the >128 KiB scenario.
243		for _, boundary := range []int{64 * 1024, 128 * 1024} {
244			any := false
245			for _, n := range sc.longLines {
246				start, end := physicalLineRange(sc.input, n)
247				if end-start <= boundary {
248					continue
249				}
250				any = true
251				for _, d := range []int{-2, -1, 0, 1, 2} {
252					at := start + boundary + d
253					schedules[fmt.Sprintf("longline%d-cut@%d", n, at)] = []int{at}
254				}
255			}
256			if !any {
257				break
258			}
259		}
260		// Delimiter neighborhoods: split one byte before/on/after the newline of
261		// every long line, and inside the first multibyte character of its key.
262		for _, n := range sc.longLines {
263			start, end := physicalLineRange(sc.input, n) // end is the '\n' index
264			for _, at := range []int{
265				start + 24, start + 25, // inside the first 3-byte rune of the key
266				end - 1, end, end + 1, end + 2, // around the line delimiter
267			} {
268				if at > 0 && at < len(sc.input) {
269					schedules[fmt.Sprintf("longline%d-near@%d", n, at)] = []int{at}
270				}
271			}
272		}
273		return schedules
274	}
275	
276	// TestAggregateLongRecordOver64KiB runs the reference scenario with records
277	// longer than 64 KiB under one-byte reads (every multibyte character and every
278	// buffer growth is split), every other fragmentation schedule, and verifies
279	// the full fixed-window contract through the public RunAggregate entry point.
280	func TestAggregateLongRecordOver64KiB(t *testing.T) {
281		sc := buildLongRecordScenario(t, 64*1024)
282	
283		// One-shot reference.
284		out, late, err := runFixedOnce(t, strings.NewReader(sc.input))
285		assertReferenceResult(t, sc, out, late, err)
286	
287		t.Run("single byte reads", func(t *testing.T) {
288			cuts := make([]int, 0, len(sc.input)-1)
289			for at := 1; at < len(sc.input); at++ {
290				cuts = append(cuts, at)
291			}
292			out, late, err := runFixedOnce(t, newChunkReader(sc.input, cuts...))
293			assertReferenceResult(t, sc, out, late, err)
294		})
295	
296		for name, cuts := range longRecordDeliverySchedules(t, sc,
297			[]int{2, 3, 7, 64, 4096, 65535, 65536, 65537}) {
298			name, cuts := name, cuts
299			if name == "one-shot" {
300				continue
301			}
302			t.Run(name, func(t *testing.T) {
303				out, late, err := runFixedOnce(t, newChunkReader(sc.input, cuts...))
304				assertReferenceResult(t, sc, out, late, err)
305			})
306		}
307	}
308	
309	// TestAggregateLongRecordOver128KiB repeats the guarantee with records longer
310	// than 128 KiB: the collector must grow past 64 KiB more than once while
311	// preserving the same bytes, order, windows and notices.
312	func TestAggregateLongRecordOver128KiB(t *testing.T) {
313		sc := buildLongRecordScenario(t, 128*1024)
314	
315		out, late, err := runFixedOnce(t, strings.NewReader(sc.input))
316		assertReferenceResult(t, sc, out, late, err)
317	
318		// Past 128 KiB the single-byte schedule is covered by the 64 KiB test;
319		// here use sizes that still force every buffer doubling and split
320		// multibyte runes without an O(n^2) run.
321		for name, cuts := range longRecordDeliverySchedules(t, sc,
322			[]int{3, 4096, 32768, 65536, 65537, 131072, 131073}) {
323			name, cuts := name, cuts
324			t.Run(name, func(t *testing.T) {
325				out, late, err := runFixedOnce(t, newChunkReader(sc.input, cuts...))
326				assertReferenceResult(t, sc, out, late, err)
327			})
328		}
329	}
330	
331	// TestAggregateLongRecordKeysDistinctAtTail is the focused guard against
332	// truncation-by-length: the two long keys share every byte except the final
333	// rune, and they must never collapse into one window row.
334	func TestAggregateLongRecordKeysDistinctAtTail(t *testing.T) {
335		for _, threshold := range []int{64 * 1024, 128 * 1024} {
336			sc := buildLongRecordScenario(t, threshold)
337			out, _, err := runFixedOnce(t, strings.NewReader(sc.input))
338			if err != nil {
339				t.Fatalf("threshold %d: unexpected error: %v", threshold, err)
340			}
341			if strings.Count(out, sc.keyA[:20]) < 2 {
342				t.Fatalf("threshold %d: expected both long keys in the output, got:\n%s", threshold, out)
343			}
344			if strings.Count(out, `"start":1000,"end":2000`) != 3 {
345				t.Fatalf("threshold %d: expected exactly three [1000,2000) rows (key A, key B, 短), got:\n%s", threshold, out)
346			}
347		}
348	}
349	
350	// TestAggregateLongRecordReadErrorDropsTail: when a genuine read failure
351	// arrives while a long record is still missing its newline, the partial tail
352	// must never become an event -- no count, no window, no late notice -- no
353	// matter where the cut lands (including inside a Chinese rune or after the
354	// buffer grew past 64/128 KiB), whether the error comes with the last bytes or
355	// on the following read. Windows already closed by earlier complete records
356	// stay written, and the caller gets the reader's own error.
357	func TestAggregateLongRecordReadErrorDropsTail(t *testing.T) {
358		ev := func(key string, time, value int) string {
359			return fmt.Sprintf(`{"type":"event","key":%q,"time":%d,"value":%d}`, key, time, value)
360		}
361		wantFirst := `{"key":"短","start":0,"end":1000,"count":1,"sum":2}` + "\n"
362	
363		for _, threshold := range []int{64 * 1024, 128 * 1024} {
364			threshold := threshold
365			t.Run(fmt.Sprintf("over%d", threshold), func(t *testing.T) {
366				keyA := longKey(longKeySuffixA, threshold)
367				head := strings.Join([]string{
368					``,
369					ev("短", 100, 2),
370					`{"type":"watermark","time":1000}`, // line 3 closes [0,1000)
371					``,
372				}, "\n") + "\n"
373				tail := ev(keyA, 1100, 10) // line 5, deliberately unterminated
374	
375				// Failure points chosen relative to the record's layout: the JSON
376				// prefix {"type":"event","key":" is 23 bytes, then the 22-byte key
377				// prefix, then 18-byte blocks of 3-byte runes -- so a cut at block
378				// start +1 lands in the middle of a Chinese rune.
379				keyStart := len(head) + len(`{"type":"event","key":"`)
380				inRuneAt := func(recordOffset int) int {
381					q := (recordOffset - (keyStart + len(longKeyPrefix))) / len(longKeyBlock)
382					return keyStart + len(longKeyPrefix) + q*len(longKeyBlock) + 1
383				}
384				cutPoints := []int{
385					len(head) + len(tail),              // whole unterminated record delivered, error afterwards
386					len(head) + len(tail) - 1,          // cut at the final '}'
387					inRuneAt(keyStart + 64*1024),       // inside a rune just past 64 KiB
388					len(head) + 23 + len(keyA) - 3 + 1, // middle of the key's final rune 甲
389				}
390				if threshold > 64*1024 {
391					cutPoints = append(cutPoints, inRuneAt(keyStart+128*1024)) // inside a rune past 128 KiB
392				}
393				type delivery struct {
394					name          string
395					chunk         int
396					errOnBoundary bool
397				}
398				deliveries := []delivery{
399					{"error on following read", 0, false},
400					{"bytes and error together", 0, true},
401					{"fragmented then error together", 4096, true},
402				}
403				if threshold == 64*1024 {
404					deliveries = append(deliveries, delivery{"one byte per read then error", 1, true})
405				}
406	
407				for _, failAt := range cutPoints {
408					for _, dl := range deliveries {
409						failAt, dl := failAt, dl
410						name := fmt.Sprintf("failAt%d/%s", failAt, dl.name)
411						t.Run(name, func(t *testing.T) {
412							if failAt < 0 || failAt > len(head)+len(tail) {
413								t.Skip("cut point beyond this key size")
414							}
415							var out, late bytes.Buffer
416							r := &failingAfterReader{
417								data:          []byte(head + tail),
418								failAt:        failAt,
419								err:           errSentinelChunkedRead,
420								chunk:         dl.chunk,
421								errOnBoundary: dl.errOnBoundary,
422							}
423							err := RunAggregate(r, 1000, &out, &late)
424							if !errors.Is(err, errSentinelChunkedRead) {
425								t.Fatalf("error = %v, want the reader's original error via errors.Is", err)
426							}
427							if _, ok := err.(*InputError); ok {
428								t.Fatalf("the partial long tail must not be reported as an input error: %v", err)
429							}
430							if out.String() != wantFirst {
431								t.Fatalf("only the previously closed window may be present:\n got: %q\nwant: %q", out.String(), wantFirst)
432							}
433							if late.String() != "" {
434								t.Fatalf("unterminated long tail must not produce a late notice: %q", late.String())
435							}
436						})
437					}
438				}
439			})
440		}
441	}
442	
443	// TestAggregateLongRecordReadErrorProcessesCompletedLines: when the failing
444	// Read also delivers complete records -- a newline-terminated long event and
445	// the watermark that closes its window -- those must be processed in order
446	// first, while an unterminated long late-event tail behind them produces no
447	// notice and no window. The reader error is what finally surfaces.
448	func TestAggregateLongRecordReadErrorProcessesCompletedLines(t *testing.T) {
449		ev := func(key string, time, value int) string {
450			return fmt.Sprintf(`{"type":"event","key":%q,"time":%d,"value":%d}`, key, time, value)
451		}
452		completed := strings.Join([]string{
453			ev("短", 100, 2),
454			`{"type":"watermark","time":1000}`, // closes [0,1000)
455			``,
456		}, "\n") + "\n"
457		wantFirst := `{"key":"短","start":0,"end":1000,"count":1,"sum":2}` + "\n"
458	
459		for _, threshold := range []int{64 * 1024, 128 * 1024} {
460			threshold := threshold
461			t.Run(fmt.Sprintf("over%d", threshold), func(t *testing.T) {
462				keyA := longKey(longKeySuffixA, threshold)
463				longEvent := ev(keyA, 1100, 10)
464				// A long late event as the final unterminated record (no closing
465				// brace, no newline): it would be judged late against watermark
466				// 2000, but without its newline it must never be judged at all.
467				lateTail := ev(keyA, 1500, 9)
468				lateTail = lateTail[:len(lateTail)-1]
469				full := completed + longEvent + "\n" +
470					`{"type":"watermark","time":2000}` + "\n" +
471					lateTail
472	
473				want := wantFirst + mustMarshalWindow(t, AggregateResult{
474					Key: keyA, Start: 1000, End: 2000, Count: 1, Sum: 10,
475				})
476	
477				type delivery struct {
478					name          string
479					chunk         int
480					errOnBoundary bool
481				}
482				deliveries := []delivery{
483					{"all bytes and error in one read", 0, true},
484					{"tail delivered clean, error next read", 0, false},
485					{"4 KiB reads, error with last bytes", 4096, true},
486				}
487				if threshold == 64*1024 {
488					deliveries = append(deliveries, delivery{"one byte per read, error with last byte", 1, true})
489				}
490				for _, dl := range deliveries {
491					dl := dl
492					t.Run(dl.name, func(t *testing.T) {
493						var out, late bytes.Buffer
494						r := &failingAfterReader{
495							data:          []byte(full),
496							failAt:        len(full),
497							err:           errSentinelChunkedRead,
498							chunk:         dl.chunk,
499							errOnBoundary: dl.errOnBoundary,
500						}
501						err := RunAggregate(r, 1000, &out, &late)
502						if !errors.Is(err, errSentinelChunkedRead) {
503							t.Fatalf("error = %v, want the reader's original error", err)
504						}
505						if out.String() != want {
506							t.Fatalf("complete records up to the newlines must be processed in order first:\n got: %q\nwant: %q", out.String(), want)
507						}
508						if late.String() != "" {
509							t.Fatalf("the unterminated long late tail must produce no notice: %q", late.String())
510						}
511					})
512				}
513			})
514		}
515	}
516	
517	// TestAggregateLongRecordCleanEOFKeepsFinalRecord pins the clean-end rule with
518	// a long record in the stream: a closing watermark that arrives as the
519	// unterminated final line at a bare io.EOF still closes the long key's window;
520	// no read failure is invented. Delivery one byte at a time must be identical.
521	func TestAggregateLongRecordCleanEOFKeepsFinalRecord(t *testing.T) {
522		ev := func(key string, time, value int) string {
523			return fmt.Sprintf(`{"type":"event","key":%q,"time":%d,"value":%d}`, key, time, value)
524		}
525		for _, threshold := range []int{64 * 1024, 128 * 1024} {
526			threshold := threshold
527			t.Run(fmt.Sprintf("over%d", threshold), func(t *testing.T) {
528				keyA := longKey(longKeySuffixA, threshold)
529				input := strings.Join([]string{
530					ev("短", 100, 2),
531					`{"type":"watermark","time":1000}`,
532					ev(keyA, 1100, 10),
533				}, "\n") + "\n" + `{"type":"watermark","time":2000}` // final record has no newline
534				want := `{"key":"短","start":0,"end":1000,"count":1,"sum":2}` + "\n" +
535					mustMarshalWindow(t, AggregateResult{Key: keyA, Start: 1000, End: 2000, Count: 1, Sum: 10})
536	
537				check := func(t *testing.T, r io.Reader) {
538					var out, late bytes.Buffer
539					if err := RunAggregate(r, 1000, &out, &late); err != nil {
540						t.Fatalf("clean EOF must not fail: %v", err)
541					}
542					if out.String() != want {
543						t.Fatalf("clean EOF output:\n got: %q\nwant: %q", out.String(), want)
544					}
545					if late.String() != "" {
546						t.Fatalf("unexpected late notices: %q", late.String())
547					}
548				}
549				t.Run("one-shot", func(t *testing.T) { check(t, strings.NewReader(input)) })
550				if threshold == 64*1024 {
551					t.Run("one byte per read", func(t *testing.T) {
552						cuts := make([]int, 0, len(input)-1)
553						for at := 1; at < len(input); at++ {
554							cuts = append(cuts, at)
555						}
556						check(t, newChunkReader(input, cuts...))
557					})
558				}
559				t.Run("64 KiB-aligned reads", func(t *testing.T) {
560					check(t, newChunkReader(input, uniformCuts(len(input), 64*1024)...))
561				})
562			})
563		}
564	}
565	
566	// mustMarshalWindow renders one expected output line (JSON object + newline).
567	func mustMarshalWindow(t *testing.T, r AggregateResult) string {
568		t.Helper()
569		encoded, err := json.Marshal(r)
570		if err != nil {
571			t.Fatalf("marshal window: %v", err)
572		}
573		return string(encoded) + "\n"
574	}
