149	// wrappedEOF is io.EOF carried in a fmt %w wrapper.
150	func wrappedEOF() error { return fmt.Errorf("connection reset at end: %w", io.EOF) }
151	
152	// TestReadAggregateLinesBareEOFOnly: the end-of-input rule must accept only
153	// the bare io.EOF sentinel. A wrapped io.EOF and a combined error containing
154	// io.EOF are read failures: the unterminated tail is dropped and the reader's
155	// own error is returned with its chain intact.
156	func TestReadAggregateLinesBareEOFOnly(t *testing.T) {
157		t.Run("wrapped io.EOF is a failure and drops the tail", func(t *testing.T) {
158			input := "first\nsecond\ntail-without-newline"
159			readErr := wrappedEOF()
160			got, err := collectLines(t, &failingAfterReader{
161				data: []byte(input), failAt: len(input),
162				err: readErr, errOnBoundary: true,
163			})
164			if err != readErr {
165				t.Fatalf("error = %v, want the reader's original error unchanged", err)
166			}
167			if !errors.Is(err, io.EOF) {
168				t.Fatalf("wrapped error must stay reachable via errors.Is: %v", err)
169			}
170			want := []collectedLine{{"first", 1}, {"second", 2}}
171			if fmt.Sprint(got) != fmt.Sprint(want) {
172				t.Fatalf("lines = %v, want only newline-terminated lines %v", got, want)
173			}
174		})
175		t.Run("combined error containing io.EOF is a failure and drops the tail", func(t *testing.T) {
176			input := "first\nsecond\ntail-without-newline"
177			readErr := &combinedEOFFailure{cause: errSentinelChunkedRead}
178			got, err := collectLines(t, &failingAfterReader{
179				data: []byte(input), failAt: len(input),
180				err: readErr, errOnBoundary: true,
181			})
182			if err != readErr {
183				t.Fatalf("error = %v, want the reader's original combined error unchanged", err)
184			}
185			if !errors.Is(err, io.EOF) {
186				t.Fatalf("errors.Is must still follow the chain to io.EOF: %v", err)
187			}
188			if !errors.Is(err, errSentinelChunkedRead) {
189				t.Fatalf("errors.Is must reach the actual failure cause: %v", err)
190			}
191			want := []collectedLine{{"first", 1}, {"second", 2}}
192			if fmt.Sprint(got) != fmt.Sprint(want) {
193				t.Fatalf("lines = %v, want only newline-terminated lines %v", got, want)
194			}
195		})
196		t.Run("combined error still completes co-delivered newline lines", func(t *testing.T) {
197			input := strings.Join([]string{
198				`{"type":"event","key":"k","time":100,"value":2}`,
199				`{"type":"watermark","time":1000}`,
200				`{"type":"event","key":"k","time":900,"value":3}`, // unterminated tail
201			}, "\n")
202			readErr := &combinedEOFFailure{cause: errSentinelChunkedRead}
203			var out, late bytes.Buffer
204			err := RunAggregate(&failingAfterReader{
205				data: []byte(input), failAt: len(input),
206				err: readErr, errOnBoundary: true,
207			}, 1000, &out, &late)
208			if err != readErr {
209				t.Fatalf("error = %v, want the combined read error unchanged", err)
210			}
211			wantWindow := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
212			if out.String() != wantWindow {
213				t.Fatalf("the newline-terminated watermark must close the window first:\n got: %q\nwant: %q", out.String(), wantWindow)
214			}
215			if late.String() != "" {
216				t.Fatalf("unterminated tail must not produce late notices: %q", late.String())
217			}
218		})
219	}
220	
221	// TestReadAggregateCombinedEOFScenario is the exact scenario from the fix
222	// report: length-1000 window, a newline-terminated event key=k time=100
223	// value=2, then a time=1000 watermark without a newline. A combined error
224	// carrying io.EOF and a read failure must fail without emitting [0,1000) and
225	// without reporting the tail as a JSON error. The same bytes at a real clean
226	// EOF must still produce count 1, sum 2.
227	func TestReadAggregateCombinedEOFScenario(t *testing.T) {
228		event := `{"type":"event","key":"k","time":100,"value":2}` + "\n"
229		watermark := `{"type":"watermark","time":1000}`
230	
231		t.Run("combined EOF failure emits nothing", func(t *testing.T) {
232			for _, tail := range []string{
233				watermark,                          // complete-looking JSON, no newline
234				`{"type":"watermark","time":1000`,  // truncated
235				`{`,                                // obviously damaged
236			} {
237				tail := tail
238				t.Run("", func(t *testing.T) {
239					input := event + tail
240					readErr := &combinedEOFFailure{cause: errSentinelChunkedRead}
241					var out, late bytes.Buffer
242					err := RunAggregate(&failingAfterReader{
243						data: []byte(input), failAt: len(input),
244						err: readErr, errOnBoundary: true,
245					}, 1000, &out, &late)
246					if err != readErr {
247						t.Fatalf("error = %v, want the combined read error unchanged", err)
248					}
249					if !errors.Is(err, errSentinelChunkedRead) {
250						t.Fatalf("errors.Is must find the read failure cause: %v", err)
251					}
252					if _, ok := err.(*InputError); ok {
253						t.Fatalf("the tail must not be reported as a JSON error: %v", err)
254					}
255					if out.String() != "" {
256						t.Fatalf("no window may close on the unterminated watermark: %q", out.String())
257					}
258					if late.String() != "" {
259						t.Fatalf("no late notices allowed: %q", late.String())
260					}
261				})
262			}
263		})
264		t.Run("wrapped EOF failure emits nothing", func(t *testing.T) {
265			input := event + watermark
266			readErr := wrappedEOF()
267			var out, late bytes.Buffer
268			err := RunAggregate(&failingAfterReader{
269				data: []byte(input), failAt: len(input),
270				err: readErr, errOnBoundary: true,
271			}, 1000, &out, &late)
272			if err != readErr {
273				t.Fatalf("error = %v, want the wrapped error unchanged", err)
274			}
275			if _, ok := err.(*InputError); ok {
276				t.Fatalf("wrapped EOF is a read failure, not an input error: %v", err)
277			}
278			if out.String() != "" {
279				t.Fatalf("wrapped EOF must not close the window: %q", out.String())
280			}
281		})
282		t.Run("same bytes at bare io.EOF produce count 1 sum 2", func(t *testing.T) {
283			input := event + watermark
284			var out, late bytes.Buffer
285			if err := RunAggregate(strings.NewReader(input), 1000, &out, &late); err != nil {
286				t.Fatalf("clean EOF must succeed: %v", err)
287			}
288			want := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
289			if out.String() != want {
290				t.Fatalf("clean EOF output:\n got: %q\nwant: %q", out.String(), want)
291			}
292			if late.String() != "" {
293				t.Fatalf("unexpected late notices: %q", late.String())
294			}
295		})
296	}
297	
298	// TestReadAggregateErrorUnterminatedTailIsNotARecord drives the exact scenario
299	// from the fix: length-1000 windows, event key=k time=100 value=2 with a
300	// newline, then a time=1000 watermark JSON without a newline, and the reader
301	// fails. The watermark must not close [0,1000); a malformed tail must not be
302	// reported as an input error either -- the read failure is what surfaces.
303	func TestReadAggregateErrorUnterminatedTailIsNotARecord(t *testing.T) {
304		event := `{"type":"event","key":"k","time":100,"value":2}` + "\n"
305		watermark := `{"type":"watermark","time":1000}`
306	
307		cases := []struct {
308			name string
309			tail string
310		}{
311			{"complete-looking watermark tail", watermark},
312			{"truncated watermark tail", `{"type":"watermark","time":1000`},
313			{"garbage tail", `{"type":wate`},
314		}
315		deliveries := []struct {
316			name           string
317			errOnBoundary  bool
318			chunk          int
319			errorAfterTail bool
320		}{
321			{"error on the next read", false, 0, true},
322			{"tail bytes and error in one read", true, 1 << 20, false},
323			{"one byte per read, error with last byte", true, 1, false},
324		}
325		for _, tc := range cases {
326			for _, dl := range deliveries {
327				name := tc.name + "/" + dl.name
328				t.Run(name, func(t *testing.T) {
329					input := event + tc.tail
330					var r io.Reader
331					if dl.errorAfterTail {
332						// The read carrying the tail succeeds; the following read fails.
333						r = &failingAfterReader{data: []byte(input), failAt: len(input), err: errSentinelChunkedRead}
334					} else {
335						r = &failingAfterReader{data: []byte(input), failAt: len(input), err: errSentinelChunkedRead, errOnBoundary: dl.errOnBoundary, chunk: dl.chunk}
336					}
337					var out, late bytes.Buffer
338					err := RunAggregate(r, 1000, &out, &late)
339					if !errors.Is(err, errSentinelChunkedRead) {
340						t.Fatalf("error = %T %v, want the reader's original error via errors.Is", err, err)
341					}
342					if _, ok := err.(*InputError); ok {
343						t.Fatalf("read failure must not be masked by a JSON/input error: %v", err)
344					}
345					if out.String() != "" {
346						t.Fatalf("unterminated watermark must not close a window, stdout = %q", out.String())
347					}
348					if late.String() != "" {
349						t.Fatalf("unterminated tail must not produce late notices: %q", late.String())
350					}
351				})
352			}
353		}
354	}
355	
356	// TestReadAggregateErrorTerminatedRecordSameReadStillProcessed: when the
357	// failing Read also delivers the watermark's newline, the window must be
358	// emitted first, in order, and only then does the run fail with the read
359	// error.
360	func TestReadAggregateErrorTerminatedRecordSameReadStillProcessed(t *testing.T) {
361		input := strings.Join([]string{
362			`{"type":"event","key":"k","time":100,"value":2}`,
363			`{"type":"watermark","time":1000}`,
364			``,
365		}, "\n") // ends with the watermark's newline
366		wantWindow := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
367	
368		check := func(t *testing.T, r io.Reader) {
369			var out, late bytes.Buffer
370			err := RunAggregate(r, 1000, &out, &late)
371			if !errors.Is(err, errSentinelChunkedRead) {
372				t.Fatalf("error = %v, want reader error after processing complete lines", err)
373			}
374			if out.String() != wantWindow {
375				t.Fatalf("window closed by the newline-terminated watermark must be emitted:\n got: %q\nwant: %q", out.String(), wantWindow)
376			}
377			if late.String() != "" {
378				t.Fatalf("unexpected late notices: %q", late.String())
379			}
380		}
381	
382		t.Run("newline and error in the same read", func(t *testing.T) {
383			check(t, &failingAfterReader{
384				data: []byte(input), failAt: len(input),
385				err: errSentinelChunkedRead, errOnBoundary: true,
386			})
387		})
388		t.Run("one byte per read, last byte with error", func(t *testing.T) {
389			check(t, &failingAfterReader{
390				data: []byte(input), failAt: len(input),
391				err: errSentinelChunkedRead, errOnBoundary: true, chunk: 1,
392			})
393		})
394	}
395	
396	// TestReadAggregateErrorUnterminatedLateEventMakesNoNoise: a tail event that
397	// the current watermark would judge late must not produce a late-event notice
398	// when the read fails before its newline arrives.
399	func TestReadAggregateErrorUnterminatedLateEventMakesNoNoise(t *testing.T) {
400		input := strings.Join([]string{
401			`{"type":"watermark","time":500}`, // line 1 complete
402			`{"type":"event","key":"k","time":100,"value":2}`,
403		}, "\n") // line 2 unterminated
404		var out, late bytes.Buffer
405		err := RunAggregate(&failingAfterReader{
406			data: []byte(input), failAt: len(input),
407			err: errSentinelChunkedRead, errOnBoundary: true,
408		}, 1000, &out, &late)
409		if !errors.Is(err, errSentinelChunkedRead) {
410			t.Fatalf("error = %v, want reader error", err)
411		}
412		if late.String() != "" {
413			t.Fatalf("unterminated late event must not yield a late notice: %q", late.String())
414		}
415		if out.String() != "" {
416			t.Fatalf("no window results possible, got %q", out.String())
417		}
418	}
419	
420	// TestReadAggregateErrorUnterminatedIdleDoesNotCloseWindows: an idle
421	// declaration whose newline never arrives must not move the partitioned
422	// effective watermark or close anything.
423	func TestReadAggregateErrorUnterminatedIdleDoesNotCloseWindows(t *testing.T) {
424		input := strings.Join([]string{
425			`{"type":"event","key":"k","time":100,"value":2,"partition":0}`,
426			`{"type":"watermark","time":1000,"partition":0}`,
427			`{"type":"idle","partition":1}`, // would make the effective watermark 1000
428		}, "\n")
429		var out, late bytes.Buffer
430		err := RunAggregatePartitionedSliding(&failingAfterReader{
431			data: []byte(input), failAt: len(input),
432			err: errSentinelChunkedRead, errOnBoundary: true,
433		}, 1000, 1000, 2, &out, &late)
434		if !errors.Is(err, errSentinelChunkedRead) {
435			t.Fatalf("error = %v, want reader error", err)
436		}
437		if out.String() != "" {
438			t.Fatalf("unterminated idle declaration must not close [0,1000): %q", out.String())
439		}
440	
441		// Control: the same idle record WITH a newline delivered together with
442		// the read error closes the window before the failure surfaces.
443		terminated := input + "\n"
444		var out2, late2 bytes.Buffer
445		err2 := RunAggregatePartitionedSliding(&failingAfterReader{
446			data: []byte(terminated), failAt: len(terminated),
447			err: errSentinelChunkedRead, errOnBoundary: true,
448		}, 1000, 1000, 2, &out2, &late2)
449		if !errors.Is(err2, errSentinelChunkedRead) {
450			t.Fatalf("control error = %v, want reader error", err2)
451		}
452		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
453		if out2.String() != want {
454			t.Fatalf("newline-terminated idle record must close the window first:\n got: %q\nwant: %q", out2.String(), want)
455		}
456	}
457	
458	// TestReadAggregateErrorEarlierRecordOrOutputFailureKept: a record error or an
459	// output write error on a complete line delivered by the same Read that
460	// carries the read failure must remain the reported failure; the read error,
461	// learned only afterwards, must not overwrite it.
462	func TestReadAggregateErrorEarlierRecordOrOutputFailureKept(t *testing.T) {
463		t.Run("record error on a complete line wins", func(t *testing.T) {
464			input := `{"type":"bogus"}` + "\n" + `{"type":"watermark","time":1000}`
465			var out, late bytes.Buffer
466			err := RunAggregate(&failingAfterReader{
467				data: []byte(input), failAt: len(input),
468				err: errSentinelChunkedRead, errOnBoundary: true,
469			}, 1000, &out, &late)
470			var ie *InputError
471			if !errors.As(err, &ie) || ie.Line != 1 {
472				t.Fatalf("error = %v, want *InputError on physical line 1", err)
473			}
474			if errors.Is(err, errSentinelChunkedRead) {
475				t.Fatalf("the record error must replace the later read error: %v", err)
476			}
477		})
478		t.Run("output write error on a complete line wins", func(t *testing.T) {
479			input := strings.Join([]string{
480				`{"type":"event","key":"k","time":100,"value":2}`,
481				`{"type":"watermark","time":1000}`,
482				`{"type":"event","key":"k","time":900,"value":3}`, // unterminated tail
483			}, "\n")
484			var late bytes.Buffer
485			err := RunAggregate(&failingAfterReader{
486				data: []byte(input), failAt: len(input),
487				err: errSentinelChunkedRead, errOnBoundary: true,
488			}, 1000, &errOnlyWriter{err: errSentinelOutput}, &late)
489			var oe *OutputError
490			if !errors.As(err, &oe) {
491				t.Fatalf("error = %v, want *OutputError", err)
492			}
493			if !errors.Is(err, errSentinelOutput) {
494				t.Fatalf("errors.Is must reach the writer error: %v", err)
495			}
496			if errors.Is(err, errSentinelChunkedRead) {
497				t.Fatalf("the output error must replace the read error learned after it: %v", err)
498			}
499		})
