501	
502	// TestReadAggregateCleanEOFContractStillHolds summarizes the behavior that had
503	// to stay byte-identical through the reader rewrite: a valid final record
504	// without a trailing newline processes at clean EOF, while a damaged final
505	// record is an input error carrying its physical line number.
506	func TestReadAggregateCleanEOFContractStillHolds(t *testing.T) {
507		t.Run("valid unterminated final record processes", func(t *testing.T) {
508			input := `{"type":"event","key":"k","time":100,"value":2}` + "\n" +
