			var stdout, stderr bytes.Buffer
			cmd.Stdout = &stdout
			cmd.Stderr = &stderr
			err := cmd.Run()
			if err == nil {
				t.Fatal("aggregate succeeded, want exit code 1 for a damaged key")
			}
			if code := cmd.ProcessState.ExitCode(); code != 1 {
