package edgefleet

import (
	"bytes"
	"strings"
	"testing"
	"time"
)

// This file guards the cost of collecting one physical line, not its result.
// The result contract for long records split across arbitrary reads lives in
// aggregate_long_record_test.go and aggregate_chunked_input_test.go. What is
// pinned here is the complexity: a valid record with a very long key must not
// make per-line work grow with the line length just because each Read brings
// only one or a few bytes. The newline scan advances over each input byte at
// most once, so the work is roughly linear in the cumulative input byte count
// (and hence in the number of reads when reads are one byte).

// singleByteCuts lists a cut before every byte except the first, the schedule
// that made the old rescanner quadratic.
func singleByteCuts(n int) []int {
	cuts := make([]int, 0, n-1)
	for at := 1; at < n; at++ {
		cuts = append(cuts, at)
	}
	return cuts
}

// singleByteLongLineStream builds a stream whose cost is dominated by one
// event record carrying a long multibyte key, closed by a watermark.
func singleByteLongLineStream(thresholdBytes int) (input string, key string) {
	key = longKey(longKeySuffixA, thresholdBytes)
	input = strings.Join([]string{
		fmtEventLine(key, 100, 7),
		`{"type":"watermark","time":1000}`,
		``,
	}, "\n")
	return input, key
}

func fmtEventLine(key string, eventTime, value int) string {
	return `{"type":"event","key":"` + jsonQuote(key) + `","time":` +
		itoa(eventTime) + `,"value":` + itoa(value) + `}`
}

// jsonQuote renders key as a JSON string body without importing a second
// encoder: the long test keys are plain multibyte text with no characters
// that need escaping.
func jsonQuote(s string) string { return s }

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b [20]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	return string(b[i:])
}

// measureSingleByteRun times one RunAggregate pass over input delivered one
// byte per Read, returning the elapsed time together with the captured output
// so the timing test also proves the run stayed correct.
func measureSingleByteRun(t *testing.T, input string) (time.Duration, string, string) {
	t.Helper()
	var out, late bytes.Buffer
	start := time.Now()
	err := RunAggregate(newChunkReader(input, singleByteCuts(len(input))...), 1000, &out, &late)
	elapsed := time.Since(start)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	return elapsed, out.String(), late.String()
}

// bestSingleByteTime measures repeated single-byte passes in batches until the
// batch spans at least minBatch, returning the best (minimum-noise) average
// per pass. Timing two stream sizes and comparing the averages is independent
// of the machine's absolute speed.
func bestSingleByteTime(t *testing.T, input string, minBatch time.Duration) time.Duration {
	t.Helper()
	iters := 1
	best := time.Duration(1<<63 - 1)
	for attempt := 0; attempt < 6; attempt++ {
		begin := time.Now()
		for i := 0; i < iters; i++ {
			var out, late bytes.Buffer
			if err := RunAggregate(newChunkReader(input, singleByteCuts(len(input))...), 1000, &out, &late); err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
		}
		batch := time.Since(begin)
		if avg := batch / time.Duration(iters); avg < best {
			best = avg
		}
		if batch >= minBatch {
			return best
		}
		// Run long enough to rise above scheduler noise, then try once more.
		iters *= 4
	}
	return best
