	if out != wantWindow {
		t.Fatalf("single-byte long-line output mismatch:\n got: %q\nwant: %q", out, wantWindow)
	}
	if late != "" {
		t.Fatalf("unexpected late notices: %q", late)
	}

	smallAvg := bestSingleByteTime(t, small, 25*time.Millisecond)
	largeAvg := bestSingleByteTime(t, large, 25*time.Millisecond)

	ratio := float64(largeAvg) / float64(smallAvg)
	if ratio > 8.0 {
		t.Fatalf("single-byte line collection is super-linear in line length: "+
			"%d-byte stream took %v/pass, %d-byte stream took %v/pass (ratio %.2f, want <= 8)",
			len(small), smallAvg, len(large), largeAvg, ratio)
	}
	// Absolute backstop against any pathology: a quarter-megabyte line is
	// roughly 270 KiB of reads, which a linear collector handles in well
	// under a second even on a slow, contended machine.
	if largeAvg > 2*time.Second {
		t.Fatalf("single-byte processing of %d bytes took %v/pass, want under 2s", len(large), largeAvg)
	}
}

// TestAggregateLineCollectionAlternatingChunksLinear interleaves long and
// short records and alternates the read size between one byte and a few
// kilobytes, so the cursor that resumes the newline search must repeatedly
// skip already-searched long tails and then find newlines inside freshly
// appended bytes. Output must equal the one-shot reference and the run must
