// This file guards the cost of collecting one physical line, not its result.
// The result contract for long records split across arbitrary reads lives in
// aggregate_long_record_test.go and aggregate_chunked_input_test.go. What is
// pinned here is the complexity: a valid record with a very long key must not
// make per-line work grow with the line length just because each Read brings
// only one or a few bytes. The newline scan advances over each input byte at
// most once, so the work is roughly linear in the cumulative input byte count
// (and hence in the number of reads when reads are one byte).

// singleByteCuts lists a cut before every byte except the first, the schedule
// that made the old rescanner quadratic.
func singleByteCuts(n int) []int {
	cuts := make([]int, 0, n-1)
	for at := 1; at < n; at++ {
		cuts = append(cuts, at)
	}
	return cuts
}

// singleByteLongLineStream builds a stream whose cost is dominated by one
// event record carrying a long multibyte key, closed by a watermark.
func singleByteLongLineStream(thresholdBytes int) (input string, key string) {
	key = longKey(longKeySuffixA, thresholdBytes)
	input = strings.Join([]string{
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":7}`, key),
		`{"type":"watermark","time":1000}`,
		``,
	}, "\n")
	return input, key
}

// bestSingleByteTime measures repeated one-byte-per-Read passes in growing
// batches until a batch spans at least minBatch, returning the best
// (minimum-noise) average per pass. Timing two stream sizes and comparing the
// averages is independent of the machine's absolute speed.
func bestSingleByteTime(t *testing.T, input string, minBatch time.Duration) time.Duration {
	t.Helper()
	cuts := singleByteCuts(len(input))
	iters := 1
	best := time.Duration(1<<63 - 1)
