		}
		if batch >= minBatch {
			return best
		}
		// Run long enough to rise above scheduler noise, then try again.
		iters *= 4
	}
	return best
}

// TestAggregateLineCollectionLinearInLineLength is the complexity guard. Two
// streams differ by a factor of four in the long line's length and in nothing
// structural; with one byte per Read a linear collector spends about four
// times longer on the larger stream, while the old rescanner spent about
// sixteen times longer (1+2+...+L byte comparisons per line). A generous
// factor of eight admits linear-with-constant-overhead behavior and rejects
// the quadratic regression without depending on absolute timings.
func TestAggregateLineCollectionLinearInLineLength(t *testing.T) {
	if testing.Short() {
		t.Skip("timing guard skipped in -short mode")
	}
	small, _ := singleByteLongLineStream(64 * 1024)
	large, largeKey := singleByteLongLineStream(256 * 1024)

	// Correctness of the timed delivery: the long key survives one-byte
	// arrival whole and the watermark closes its window.
	var out, late bytes.Buffer
	if err := RunAggregate(newChunkReader(large, singleByteCuts(len(large))...), 1000, &out, &late); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	wantWindow := fmt.Sprintf(`{"key":%q,"start":0,"end":1000,"count":1,"sum":7}`+"\n", largeKey)
	if out.String() != wantWindow {
		t.Fatalf("single-byte long-line output mismatch:\n got: %q\nwant: %q", out.String(), wantWindow)
	}
